import React, { useState, useEffect, useContext } from 'react';
import { Link } from 'react-router-dom';
import { Users, UserPlus, Search, Filter, Edit3, CheckCircle2, XCircle, GraduationCap, Mail, Phone, BookOpen, Star, MoreVertical, ChevronRight, X, Sparkles, TrendingUp, ShieldCheck, Hash } from 'lucide-react';
import { AppContext } from '../../App';
import { StudentService } from '../../domain/studentService';

const StudentManagement = () => {
  const { userType } = useContext(AppContext);
  const [students, setStudents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [selectedStudent, setSelectedStudent] = useState(null);
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    studentId: '',
    department: '',
    year: '',
    cgpa: '',
    skills: '',
    certifications: ''
  });
  const [message, setMessage] = useState('');
  const [formLoading, setFormLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    loadStudents();
  }, []);

  const loadStudents = async () => {
    try {
      setLoading(true);
      const studentsData = await StudentService.getAllStudents();
      setStudents(studentsData);
    } catch (error) {
      console.error('Failed to load students:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleAddStudent = () => {
    setSelectedStudent(null);
    setIsEditing(false);
    setFormData({
      name: '',
      email: '',
      phone: '',
      studentId: '',
      department: '',
      year: '',
      cgpa: '',
      skills: '',
      certifications: ''
    });
    setMessage('');
    setShowModal(true);
  };

  const handleEditStudent = (student) => {
    setSelectedStudent(student);
    setIsEditing(true);
    setFormData({
      name: student.name,
      email: student.email,
      phone: student.phone,
      studentId: student.studentId,
      department: student.department,
      year: student.year.toString(),
      cgpa: student.cgpa.toString(),
      skills: student.skills ? student.skills.join(', ') : '',
      certifications: student.certifications ? student.certifications.join(', ') : ''
    });
    setMessage('');
    setShowModal(true);
  };

  const handleInputChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setFormLoading(true);
    setMessage('');

    try {
      const studentData = {
        ...formData,
        year: parseInt(formData.year),
        cgpa: parseFloat(formData.cgpa),
        skills: formData.skills.split(',').map(skill => skill.trim()).filter(skill => skill),
        certifications: formData.certifications.split(',').map(cert => cert.trim()).filter(cert => cert)
      };

      if (isEditing) {
        await StudentService.updateStudentProfile(selectedStudent.id, studentData);
        setMessage('Portfolio successfully synchronized.');
      } else {
        await StudentService.registerStudent(studentData);
        setMessage('New talent cataloged successfully.');
      }

      setTimeout(() => {
        setShowModal(false);
        loadStudents();
      }, 2000);
    } catch (error) {
      setMessage(error.message);
    } finally {
      setFormLoading(false);
    }
  };

  const getEligibilityBadge = (isEligible) => {
    return isEligible ? (
      <span className="bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest flex items-center gap-2">
        <ShieldCheck size={12} /> Eligible
      </span>
    ) : (
      <span className="bg-rose-500/10 text-rose-400 border border-rose-500/20 px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest flex items-center gap-2">
        <XCircle size={12} /> Restricted
      </span>
    );
  };

  const filteredStudents = students.filter(s => 
    s.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.studentId.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.department.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return (
      <div className="min-h-screen bg-onyx-900 flex items-center justify-center">
        <div className="w-12 h-12 border-4 border-gold-500/20 border-t-gold-500 rounded-full animate-spin"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-onyx-900 pb-24 font-sans text-pearl-200">
      {/* Cinematic Header */}
      <div className="h-64 bg-onyx-950 relative overflow-hidden">
        <div className="absolute inset-0 bg-gold-gradient opacity-[0.03]"></div>
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[1000px] h-[1000px] bg-gold-500/5 rounded-full blur-[150px]"></div>

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-full flex flex-col justify-center relative z-10">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-8">
            <div>
              <h1 className="text-4xl md:text-6xl font-serif font-bold text-white tracking-tight leading-none mb-4">Talent Registry</h1>
              <p className="text-pearl-500 text-lg font-light tracking-wide italic">Curating and managing the academic elite.</p>
            </div>
            {userType === 'admin' && (
              <button 
                onClick={handleAddStudent}
                className="bg-gold-gradient text-onyx-900 px-8 py-4 rounded-2xl font-black uppercase tracking-[0.2em] text-xs hover:brightness-110 transition-all shadow-gold flex items-center gap-3 w-fit"
              >
                <UserPlus size={18} /> Catalog New Talent
              </button>
            )}
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 -mt-12 relative z-20">

        {/* Statistics Bar */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-12">
          <div className="glass rounded-3xl p-8 border border-pearl-900/10 shadow-xl group hover:border-gold-500/30 transition-all">
            <div className="flex justify-between items-start mb-4">
              <div className="w-12 h-12 rounded-2xl bg-white/5 flex items-center justify-center text-pearl-500 group-hover:text-gold-500 transition-colors">
                <Users size={24} />
              </div>
              <TrendingUp size={16} className="text-emerald-500" />
            </div>
            <p className="text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-1">Total Catalog</p>
            <h3 className="text-4xl font-serif font-bold text-white leading-none">{students.length}</h3>
          </div>

          <div className="glass rounded-3xl p-8 border border-pearl-900/10 shadow-xl group hover:border-gold-500/30 transition-all">
            <div className="flex justify-between items-start mb-4">
              <div className="w-12 h-12 rounded-2xl bg-white/5 flex items-center justify-center text-pearl-500 group-hover:text-gold-500 transition-colors">
                <ShieldCheck size={24} />
              </div>
              <Sparkles size={16} className="text-gold-500 animate-pulse" />
            </div>
            <p className="text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-1">Elite (Eligible)</p>
            <h3 className="text-4xl font-serif font-bold text-white leading-none">{students.filter(s => s.isEligible).length}</h3>
          </div>

          <div className="glass rounded-3xl p-8 border border-pearl-900/10 shadow-xl group hover:border-gold-500/30 transition-all">
            <div className="flex justify-between items-start mb-4">
              <div className="w-12 h-12 rounded-2xl bg-white/5 flex items-center justify-center text-pearl-500 group-hover:text-gold-500 transition-colors">
                <GraduationCap size={24} />
              </div>
              <span className="text-[10px] font-bold text-gold-500 uppercase tracking-widest">Final</span>
            </div>
            <p className="text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-1">Senior Tier</p>
            <h3 className="text-4xl font-serif font-bold text-white leading-none">{students.filter(s => s.year === 4).length}</h3>
          </div>

          <div className="glass rounded-3xl p-8 border border-pearl-900/10 shadow-xl group hover:border-gold-500/30 transition-all">
            <div className="flex justify-between items-start mb-4">
              <div className="w-12 h-12 rounded-2xl bg-white/5 flex items-center justify-center text-pearl-500 group-hover:text-gold-500 transition-colors">
                <Star size={24} />
              </div>
              <TrendingUp size={16} className="text-emerald-500" />
            </div>
            <p className="text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-1">High Achievers (8.0+)</p>
            <h3 className="text-4xl font-serif font-bold text-white leading-none">{students.filter(s => s.cgpa >= 8.0).length}</h3>
          </div>
        </div>

        {/* Search & Filter Bar */}
        <div className="glass rounded-[2.5rem] border border-pearl-900/10 p-4 mb-10 flex flex-col md:flex-row gap-4 items-center shadow-2xl">
          <div className="relative flex-1 w-full">
            <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-pearl-700" size={20} />
            <input 
              type="text" 
              placeholder="Search by name, ID, or department..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-onyx-800/50 border border-pearl-900/10 rounded-2xl py-4 pl-16 pr-6 text-white outline-none focus:border-gold-500/50 transition-all font-light"
            />
          </div>
          <button className="glass px-8 py-4 rounded-2xl border border-pearl-900/10 text-pearl-400 font-bold flex items-center gap-3 hover:bg-white/5 transition-all">
            <Filter size={20} /> Parameters
          </button>
        </div>

        {/* Talent Table */}
        <div className="glass rounded-[3rem] border border-pearl-900/10 overflow-hidden shadow-2xl">
          <div className="px-10 py-8 border-b border-pearl-900/10 flex justify-between items-center bg-white/5">
            <h3 className="text-2xl font-serif font-bold text-white">Talent Catalog</h3>
            <span className="text-[10px] font-black text-pearl-700 uppercase tracking-[0.3em] italic">Full Registry</span>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-onyx-950/50 text-pearl-700 text-[10px] uppercase tracking-[0.2em] font-black">
                  <th className="py-8 px-10">Professional</th>
                  <th className="py-8 px-10">Department</th>
                  <th className="py-8 px-10">Year</th>
                  <th className="py-8 px-10">Metric (CGPA)</th>
                  <th className="py-8 px-10">Status</th>
                  <th className="py-8 px-10 text-right">Operations</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-pearl-900/5">
                {filteredStudents.map(student => (
                  <tr key={student.id} className="hover:bg-white/[0.02] transition-colors group">
                    <td className="py-8 px-10">
                      <Link to={`/student/${student.id}`} className="flex items-center gap-5 group/link">
                        <div className="w-14 h-14 rounded-2xl bg-onyx-800 p-1 border border-pearl-900/10 overflow-hidden shrink-0 group-hover/link:border-gold-500/30 transition-all">
                          <img src={`https://api.dicebear.com/7.x/initials/svg?seed=${student.name}`} alt="Avatar" className="w-full h-full object-cover grayscale group-hover/link:grayscale-0 transition-all duration-500" />
                        </div>
                        <div>
                          <p className="font-serif font-bold text-white text-xl tracking-tight leading-tight group-hover/link:text-gold-400 transition-colors">{student.name}</p>
                          <p className="text-pearl-600 text-[10px] font-black uppercase tracking-widest flex items-center gap-2 mt-1">
                             <Hash size={10} className="text-gold-500/30" /> {student.studentId}
                          </p>
                        </div>
                      </Link>
                    </td>
                    <td className="py-8 px-10">
                      <span className="text-pearl-400 font-light text-sm uppercase tracking-widest">{student.department}</span>
                    </td>
                    <td className="py-8 px-10">
                      <div className="flex flex-col">
                         <span className="text-white font-bold text-sm">Year {student.year}</span>
                         <span className="text-pearl-700 text-[9px] font-black uppercase tracking-widest mt-0.5">Tier</span>
                      </div>
                    </td>
                    <td className="py-8 px-10">
                      <div className="flex items-center gap-3">
                         <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-bold text-sm ${student.cgpa >= 8.0 ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' : student.cgpa >= 7.0 ? 'bg-gold-500/10 text-gold-500 border border-gold-500/20' : 'bg-rose-500/10 text-rose-400 border border-rose-500/20'}`}>
                           {student.cgpa}
                         </div>
                         <div className="h-1 w-12 bg-white/5 rounded-full overflow-hidden">
                            <div className="h-full bg-gold-gradient transition-all duration-1000" style={{ width: `${student.cgpa * 10}%` }}></div>
                         </div>
                      </div>
                    </td>
                    <td className="py-8 px-10">
                      {getEligibilityBadge(student.isEligible)}
                    </td>
                    <td className="py-8 px-10 text-right">
                      <div className="flex gap-3 justify-end opacity-0 group-hover:opacity-100 transition-opacity">
                        <Link 
                          to={`/student/${student.id}`}
                          className="w-10 h-10 rounded-xl glass border border-pearl-900/10 flex items-center justify-center text-pearl-600 hover:text-white hover:border-pearl-200 transition-all"
                        >
                          <ChevronRight size={18} />
                        </Link>
                        {userType === 'admin' && (
                          <button 
                            onClick={() => handleEditStudent(student)}
                            className="w-10 h-10 rounded-xl glass border border-pearl-900/10 flex items-center justify-center text-pearl-600 hover:text-gold-500 hover:border-gold-500/30 transition-all"
                          >
                            <Edit3 size={18} />
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {filteredStudents.length === 0 && (
            <div className="p-24 text-center">
              <div className="w-24 h-24 bg-onyx-800 rounded-3xl flex items-center justify-center mx-auto mb-8 border border-pearl-900/10">
                <Search className="text-pearl-800" size={40} />
              </div>
              <h4 className="text-2xl font-serif font-bold text-white mb-2">No talent discovered</h4>
              <p className="text-pearl-600 font-light italic">Refine your strategic parameters and search again.</p>
            </div>
          )}
        </div>
      </div>

      {/* Add/Edit Talent Modal */}
      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6 bg-onyx-950/80 backdrop-blur-md overflow-y-auto">
          <div className="glass rounded-[3.5rem] w-full max-w-4xl shadow-[0_0_80px_rgba(0,0,0,0.6)] border border-pearl-900/10 overflow-hidden my-auto animate-fade-in-up">
            <div className="px-10 py-8 border-b border-pearl-900/10 flex justify-between items-center bg-white/5">
              <h3 className="text-2xl font-serif font-bold text-white">
                {isEditing ? 'Sync Talent Portfolio' : 'Catalog New Talent'}
              </h3>
              <button onClick={() => setShowModal(false)} className="text-pearl-600 hover:text-white bg-onyx-800 p-3 rounded-2xl transition-all border border-pearl-900/10">
                <X size={20} />
              </button>
            </div>

            <div className="p-10 max-h-[75vh] overflow-y-auto custom-scrollbar">
              {message && (
                <div className={`p-5 rounded-2xl mb-8 font-bold text-sm uppercase tracking-widest flex items-start gap-4 ${message.includes('successfully') || message.includes('synchronized') || message.includes('cataloged') ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' : 'bg-rose-500/10 text-rose-400 border border-rose-500/20'}`}>
                  {message.includes('successfully') ? <CheckCircle2 size={20} className="shrink-0" /> : <X size={20} className="shrink-0" />}
                  <p>{message}</p>
                </div>
              )}

              <form onSubmit={handleSubmit} className="space-y-12">

                {/* Identity Section */}
                <div>
                  <h4 className="text-[10px] font-black text-gold-500 uppercase tracking-[0.3em] mb-8 flex items-center gap-3">
                    <span className="w-8 h-px bg-gold-500/30"></span>
                    Identity & ID
                  </h4>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    <div>
                      <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3 ml-1">Full Name</label>
                      <div className="relative group">
                         <Sparkles className="absolute left-5 top-1/2 -translate-y-1/2 text-pearl-800 group-focus-within:text-gold-500 transition-colors" size={18} />
                         <input type="text" name="name" value={formData.name} onChange={handleInputChange} required className="w-full px-5 py-4 pl-14 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white" />
                      </div>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3 ml-1">Student Identifier (ID)</label>
                      <div className="relative group">
                         <Hash className="absolute left-5 top-1/2 -translate-y-1/2 text-pearl-800 group-focus-within:text-gold-500 transition-colors" size={18} />
                         <input type="text" name="studentId" value={formData.studentId} onChange={handleInputChange} required className="w-full px-5 py-4 pl-14 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white" />
                      </div>
                    </div>
                  </div>
                </div>

                {/* Connectivity Section */}
                <div>
                  <h4 className="text-[10px] font-black text-gold-500 uppercase tracking-[0.3em] mb-8 flex items-center gap-3">
                    <span className="w-8 h-px bg-gold-500/30"></span>
                    Connectivity Channels
                  </h4>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    <div>
                      <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3 ml-1">Official Email</label>
                      <div className="relative group">
                        <Mail className="absolute left-5 top-1/2 -translate-y-1/2 text-pearl-800 group-focus-within:text-gold-500 transition-colors" size={18} />
                        <input type="email" name="email" value={formData.email} onChange={handleInputChange} required className="w-full px-5 py-4 pl-14 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white" />
                      </div>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3 ml-1">Secure Phone Line</label>
                      <div className="relative group">
                        <Phone className="absolute left-5 top-1/2 -translate-y-1/2 text-pearl-800 group-focus-within:text-gold-500 transition-colors" size={18} />
                        <input type="tel" name="phone" value={formData.phone} onChange={handleInputChange} required className="w-full px-5 py-4 pl-14 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white" />
                      </div>
                    </div>
                  </div>
                </div>

                {/* Academic Profile Section */}
                <div>
                  <h4 className="text-[10px] font-black text-gold-500 uppercase tracking-[0.3em] mb-8 flex items-center gap-3">
                    <span className="w-8 h-px bg-gold-500/30"></span>
                    Academic Trajectory
                  </h4>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mb-8">
                    <div className="md:col-span-2">
                      <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3 ml-1">Academic Vertical (Department)</label>
                      <select name="department" value={formData.department} onChange={handleInputChange} required className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white appearance-none cursor-pointer">
                        <option value="">Select Vertical</option>
                        <option value="Computer Science">Computer Science</option>
                        <option value="Information Technology">Information Technology</option>
                        <option value="Electronics">Electronics</option>
                        <option value="Mechanical">Mechanical</option>
                        <option value="Civil">Civil</option>
                        <option value="Electrical">Electrical</option>
                      </select>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3 ml-1">Academic Tier (Year)</label>
                      <select name="year" value={formData.year} onChange={handleInputChange} required className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white appearance-none cursor-pointer">
                        <option value="">Select Tier</option>
                        <option value="1">1st Year Entry</option>
                        <option value="2">2nd Year Progression</option>
                        <option value="3">3rd Year Advanced</option>
                        <option value="4">4th Year Senior</option>
                      </select>
                    </div>
                  </div>

                  <div>
                    <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3 ml-1">Performance Metric (CGPA)</label>
                    <div className="relative group">
                       <TrendingUp className="absolute left-5 top-1/2 -translate-y-1/2 text-pearl-800 group-focus-within:text-gold-500 transition-colors" size={18} />
                       <input type="number" step="0.01" min="0" max="10" name="cgpa" value={formData.cgpa} onChange={handleInputChange} required className="w-full px-5 py-4 pl-14 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white" />
                    </div>
                  </div>
                </div>

                {/* Specialized Skills & Certs */}
                <div>
                  <h4 className="text-[10px] font-black text-gold-500 uppercase tracking-[0.3em] mb-8 flex items-center gap-3">
                    <span className="w-8 h-px bg-gold-500/30"></span>
                    Skills & Accolades
                  </h4>
                  <div className="space-y-8">
                    <div>
                      <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3 ml-1">Strategic Competencies</label>
                      <textarea rows={2} name="skills" value={formData.skills} onChange={handleInputChange} placeholder="JavaScript, React, System Architecture, etc." className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-light text-pearl-300 resize-none leading-relaxed" />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3 ml-1">Certified Accomplishments</label>
                      <textarea rows={2} name="certifications" value={formData.certifications} onChange={handleInputChange} placeholder="AWS Certified Solutions Architect, Google Cloud Professional, etc." className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-light text-pearl-300 resize-none leading-relaxed" />
                    </div>
                  </div>
                </div>

                <div className="pt-10 flex gap-5 justify-end">
                  <button type="button" onClick={() => setShowModal(false)} disabled={formLoading} className="px-10 py-4 rounded-2xl font-bold text-pearl-500 glass hover:text-white transition-all text-xs uppercase tracking-[0.2em]">
                    Dismiss
                  </button>
                  <button type="submit" disabled={formLoading} className="px-12 py-4 rounded-2xl font-bold text-onyx-900 bg-gold-gradient hover:brightness-110 transition-all shadow-gold flex items-center gap-4 text-xs uppercase tracking-[0.2em]">
                    {formLoading ? (
                      <><div className="w-4 h-4 border-2 border-onyx-900/30 border-t-onyx-900 rounded-full animate-spin"></div> Syncing...</>
                    ) : (isEditing ? 'Synchronize Portfolio' : 'Execute Cataloging')}
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default StudentManagement;
